import csv

# Load patient sex data
male_ids = set()
with open('patient_sex.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    id_idx = header.index('ID')
    sex_idx = header.index('SEX')
    for row in reader:
        if row[sex_idx] == 'M':
            male_ids.add(row[id_idx])

# Find the 2 patients with abnormal FG
abnormal_fg_patients = []

with open('csv/Laboratory.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    id_idx = header.index('ID')
    wbc_idx = header.index('WBC')
    fg_idx = header.index('FG')

    for row in reader:
        patient_id = row[id_idx]
        if patient_id in male_ids:
            wbc = row[wbc_idx].strip()
            if wbc:
                try:
                    wbc_val = float(wbc)
                    if 4.0 <= wbc_val <= 11.0:
                        fg = row[fg_idx].strip()
                        if fg:
                            try:
                                fg_val = float(fg)
                                if fg_val < 2.0 or fg_val > 4.0:
                                    abnormal_fg_patients.append((patient_id, wbc_val, fg_val))
                            except:
                                pass
                except:
                    pass

print(f'Number of male patients with normal WBC and abnormal FG: {len(abnormal_fg_patients)}')
print('Details:')
for p in abnormal_fg_patients:
    print(f'  Patient {p[0]}: WBC={p[1]}, FG={p[2]}')

